// Correctness on real binaries built with zig cc (clang) for 8 targets. Expected values come from
// samples/disasm/reference.json, generated by capstone 5, pyelftools, pefile and macholib
// (samples/disasm/src/make-reference.py). Python is not needed to run these tests.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  openProgram, resolveFunction, disasmFunction, disasmPseudocode, disasmXrefs, disasmCallgraph, disasmSearch,
  disasmFindReferences, disasmCallPaths, disasmAt, disasmListFunctions, disasmInfo, TOOLS, CLI_COMMANDS, disasmAnalyzer, normName,
} from '../src/node.ts';

const here = dirname(fileURLToPath(import.meta.url));
const dir = join(here, '..', '..', '..', 'samples', 'disasm');
const ref = JSON.parse(readFileSync(join(dir, 'reference.json'), 'utf8'));
const P = (n: string) => join(dir, n);
const hx = (n: number) => '0x' + n.toString(16);

interface RefInsn { addr: number; mnemonic: string; op_str: string; size: number }

// iced-x86 and capstone spell a few x86 mnemonics differently
const X86_ALIASES: Record<string, string> = { movabs: 'mov', 'cs nop': 'nop', 'nop word ptr': 'nop' };
const normMn = (m: string) => X86_ALIASES[m] ?? m;

const NATIVE = ['hello-x64.elf', 'hello-arm64.elf', 'hello-x86.elf', 'hello-arm32.elf', 'hello-thumb-static.elf', 'hello-x64.macho', 'hello-arm64.macho'];

for (const file of NATIVE) {
  const r = ref[file];
  test(`${file}: entry, symbols and function addresses match ${r.format === 'macho' ? 'macholib' : 'pyelftools'}`, async () => {
    const p = await openProgram({ path: P(file) });
    assert.equal(p.img.arch, r.arch);
    assert.equal(p.img.entry, r.entry);
    for (const [name, f] of Object.entries<{ addr: number }>(r.functions)) {
      const got = resolveFunction(p, name);
      assert.ok(got, `${name} not found`);
      assert.equal(got!.addr, f.addr, `${name} address`);
    }
  });

  test(`${file}: first instructions of main match capstone`, async () => {
    const main = r.functions.main;
    const d = await disasmFunction({ path: P(file), function: 'main', limit: 64 });
    const flat = d.blocks.flatMap((b) => b.insns) as { addr: string; text: string; bytes: string }[];
    const byAddr = new Map(flat.map((i) => [i.addr, i]));
    const x86 = r.arch === 'x86' || r.arch === 'x86_64';
    let compared = 0;
    for (const ci of main.first as RefInsn[]) {
      const mine = byAddr.get(hx(ci.addr));
      if (!mine) continue; // capstone sweeps linearly past the CFG (padding after ret)
      compared++;
      assert.equal(mine.bytes.length / 2, ci.size, `size at ${hx(ci.addr)}`);
      const [mn] = mine.text.split(' ');
      if (x86) assert.equal(normMn(mn!), normMn(ci.mnemonic), `mnemonic at ${hx(ci.addr)}: ${mine.text} vs ${ci.mnemonic} ${ci.op_str}`);
      else assert.equal(mine.text, `${ci.mnemonic} ${ci.op_str}`.trim(), `text at ${hx(ci.addr)}`);
    }
    assert.ok(compared >= 8, `compared ${compared} instructions`);
  });

  test(`${file}: direct calls in main match capstone call targets`, async () => {
    const p = await openProgram({ path: P(file) });
    const af = p.analyze(r.functions.main.addr)!;
    const mine = new Set(af.calls.filter((c) => !c.tail && c.target !== undefined).map((c) => `${hx(c.at)}->${hx(c.target!)}`));
    const end = Math.max(...af.blocks.map((b) => b.end));
    const expected = (r.functions.main.calls as { at: number; target: number }[]).filter((c) => c.at < end && c.target !== c.at + 5 /* call $+5 is the x86-32 PIC idiom, not a call */).map((c) => `${hx(c.at)}->${hx(c.target)}`);
    assert.ok(expected.length >= 5);
    for (const e of expected) assert.ok(mine.has(e), `missing call ${e}`);
    const names = af.calls.map((c) => normName(c.name ?? ''));
    for (const n of ['classify', 'sum_to', 'check_password', 'deep1', 'fib', 'printf']) assert.ok(names.includes(n), `main calls ${n}`);
  });

  test(`${file}: check_password references the strings and calls strcmp and puts`, async () => {
    const p = await openProgram({ path: P(file) });
    const af = p.analyze(r.functions.check_password.addr)!;
    const strs = af.dataRefs.filter((d) => d.kind === 'string');
    for (const s of ['access granted', 'access denied', 'revlens-secret-key']) {
      const hit = strs.find((d) => d.value === s);
      assert.ok(hit, `string ${s}`);
      assert.equal(hit!.addr, r.strings[s], `address of ${s}`);
    }
    const calls = af.calls.map((c) => normName(c.name ?? ''));
    assert.ok(calls.includes('strcmp'), 'strcmp call resolved by name: ' + calls.join(','));
    assert.ok(calls.includes('puts'), 'puts call resolved by name');
    const fr = await disasmFindReferences({ path: P(file), string: 'access granted' });
    assert.ok(fr.functions.some((f) => normName(f) === 'check_password'));
    assert.equal(fr.matches[0]!.target, hx(r.strings['access granted']));
  });

  test(`${file}: call path main -> deep1 -> deep2 -> deep3`, async () => {
    const cp = await disasmCallPaths({ path: P(file), target: 'deep3', from: 'main' });
    assert.ok(cp.reachable);
    assert.deepEqual(cp.paths[0]!.map(normName), ['main', 'deep1', 'deep2', 'deep3']);
  });
}

test('ELF import slots match the .rela.plt / .rel.plt relocations (pyelftools)', async () => {
  for (const file of ['hello-x64.elf', 'hello-arm64.elf', 'hello-x86.elf', 'hello-arm32.elf']) {
    const p = await openProgram({ path: P(file) });
    for (const imp of ref[file].imports as { name: string; slot: number }[]) {
      const mine = p.importBySlot.get(imp.slot);
      assert.equal(mine?.name, imp.name, `${file} slot ${hx(imp.slot)}`);
      if (imp.name !== '__libc_start_main' && imp.name !== 'abort') assert.ok(mine?.stub !== undefined, `${file}: PLT stub for ${imp.name}`);
    }
  }
});

test('stripped ELF: main recovered from _start and functions found from .eh_frame and calls', async () => {
  const full = ref['hello-x64.elf'];
  const p = await openProgram({ path: P('hello-x64-stripped.elf') });
  const main = resolveFunction(p, 'main');
  assert.equal(main?.addr, full.functions.main.addr);
  for (const name of ['check_password', 'sum_to', 'fib', 'deep3']) assert.ok(p.functions.has(full.functions[name].addr), `${name} discovered`);
  const fr = await disasmFindReferences({ path: P('hello-x64-stripped.elf'), string: 'access granted' });
  assert.equal(fr.matches[0]!.refs[0]!.functionAddr, hx(full.functions.check_password.addr));
});

test('PE x64: imports match pefile, string xref matches capstone sweep, IAT calls named', async () => {
  const r = ref['hello-x64.exe'];
  const p = await openProgram({ path: P('hello-x64.exe') });
  assert.equal(p.img.entry, r.entry);
  for (const imp of r.imports as { name: string; slot: number; library: string }[]) {
    const mine = p.importBySlot.get(imp.slot);
    assert.equal(mine?.name, imp.name);
    assert.equal(mine?.library, imp.library);
  }
  for (const a of r.pdata_first as number[]) assert.ok(p.discover().has(a), `pdata function ${hx(a)}`);
  const fr = await disasmFindReferences({ path: P('hello-x64.exe'), string: 'access granted' });
  assert.deepEqual(fr.matches[0]!.refs.map((x) => x.from), (r.access_granted_refs as number[]).map(hx));
  const fn = fr.matches[0]!.refs[0]!.functionAddr;
  const af = p.analyze(parseInt(fn, 16))!;
  const names = af.calls.map((c) => c.name);
  assert.ok(names.includes('strcmp') && names.includes('puts'), names.join(','));
  const imp = await disasmFindReferences({ path: P('hello-x64.exe'), import: 'strcmp', exact: true });
  assert.equal(imp.matches[0]!.refs[0]!.functionAddr, fn);
  // entry point bytes decode like capstone
  const at = await disasmAt({ path: P('hello-x64.exe'), address: hx(r.entry), count: 8 });
  (r.entry_first as RefInsn[]).forEach((ci, k) => assert.equal(normMn((at.instructions[k]!.text as string).split(' ')[0]!), normMn(ci.mnemonic)));
});

test('fat Mach-O: x86_64 slice by default, arm64 on request, addresses match macholib', async () => {
  const r = ref['hello-fat.macho'];
  const a = await openProgram({ path: P('hello-fat.macho') });
  assert.equal(a.img.arch, 'x86_64');
  assert.equal(a.img.slices?.length, 2);
  assert.equal(resolveFunction(a, 'main')?.addr, r.x86_64.functions.main.addr);
  const b = await openProgram({ path: P('hello-fat.macho'), arch: 'arm64' });
  assert.equal(b.img.arch, 'arm64');
  assert.equal(b.img.fileOffset, r.arm64.slice_offset);
  assert.equal(resolveFunction(b, 'main')?.addr, r.arm64.functions.main.addr);
  assert.equal(b.img.entry, r.arm64.entry);
  const s = await disasmFindReferences({ path: P('hello-fat.macho'), arch: 'arm64', string: 'revlens-secret-key' });
  assert.equal(s.matches[0]!.target, hx(r.arm64.strings['revlens-secret-key']));
});

test('Mach-O stubs: calls through __stubs resolve to import names', async () => {
  for (const file of ['hello-x64.macho', 'hello-arm64.macho']) {
    const p = await openProgram({ path: P(file) });
    const [stubStart, stubSize] = ref[file].stubs[0] as [number, number];
    const stubs = [...p.importByStub.keys()];
    assert.ok(stubs.length >= 3);
    for (const s of stubs) assert.ok(s >= stubStart && s < stubStart + stubSize);
    const x = await disasmXrefs({ path: P(file), target: '_puts' });
    assert.ok(x.refs.some((q) => normName(q.function) === 'check_password'), JSON.stringify(x.refs));
  }
});

test('pseudocode: structured if/else and loops with inlined calls and strings', async () => {
  const main = await disasmPseudocode({ path: P('hello-x64.elf'), function: 'main' });
  assert.match(main.pseudocode, /printf\("hello from revlens %d\\n"/);
  assert.match(main.pseudocode, /check_password\(/);
  assert.match(main.pseudocode, /if \(/);
  const sum = await disasmPseudocode({ path: P('hello-arm64.elf'), function: 'sum_to' });
  assert.match(sum.pseudocode, /do \{|while \(/);
  assert.ok(sum.summary.loops >= 1);
  const d2 = await disasmPseudocode({ path: P('hello-x64.elf'), function: 'deep2' });
  // deep2(int v): the parameter is named a1 and the void return type is recovered
  assert.match(d2.pseudocode, /void deep2\(int64_t a1\) \{\n  if \(a1 >= 2\) \{[\s\S]*return deep3\(\);/);
  assert.equal(d2.gotos, 0);
  const cp = await disasmPseudocode({ path: P('hello-thumb-static.elf'), function: 'check_password' });
  assert.match(cp.pseudocode, /"revlens-secret-key"/);
  assert.equal(cp.summary.strings.length, 3);
});

test('xrefs, callgraph, search, list and info tools', async () => {
  const f = P('hello-x64.elf');
  const x = await disasmXrefs({ path: f, target: 'check_password' });
  assert.deepEqual(x.refs.map((q) => q.function), ['main']);
  const from = await disasmXrefs({ path: f, target: 'main', direction: 'from' });
  assert.ok(from.refs.some((q) => q.name === 'hello from revlens %d\n'));
  const cg = await disasmCallgraph({ path: f, function: 'main', depth: 2 });
  const names = cg.nodes.map((n) => n.name);
  for (const n of ['check_password', 'printf', 'deep2', 'strcmp']) assert.ok(names.includes(n), n);
  const callers = await disasmCallgraph({ path: f, function: 'deep3', direction: 'callers', depth: 3 });
  assert.ok(callers.nodes.some((n) => n.name === 'main'));
  const mainAddr = ref['hello-x64.elf'].functions.main.addr;
  const first = ref['hello-x64.elf'].functions.main.first as RefInsn[];
  const p = await openProgram({ path: f });
  const bytes = [...p.mem.view(mainAddr, 8)].map((b) => b.toString(16).padStart(2, '0'));
  const s1 = await disasmSearch({ path: f, bytes_pattern: `${bytes.slice(0, 4).join(' ')} ?? ${bytes.slice(5, 8).join(' ')}` });
  assert.ok(s1.matches.some((m) => m.addr === hx(mainAddr)));
  const s2 = await disasmSearch({ path: f, insn: 'call *check_password*' });
  assert.equal(s2.matches.length, 1);
  assert.equal(s2.matches[0]!.function, 'main');
  const s3 = await disasmSearch({ path: f, text: 'access granted' });
  assert.equal(s3.matches[0]!.addr, hx(ref['hello-x64.elf'].strings['access granted']));
  const l = await disasmListFunctions({ path: f, filter: 'deep', sort: 'name' });
  assert.deepEqual(l.functions.map((q) => q.name), ['deep1', 'deep2', 'deep3']);
  const paged = await disasmListFunctions({ path: f, limit: 2, offset: 1 });
  assert.equal(paged.functions.length, 2);
  assert.ok(paged.hasMore);
  const info = await disasmInfo({ path: f });
  assert.equal(info.decoder, 'iced-x86');
  const at = await disasmAt({ path: f, address: 'main', count: 3 });
  assert.equal(at.instructions.length, 3);
  assert.equal(normMn((at.instructions[0]!.text as string).split(' ')[0]!), first[0]!.mnemonic);
});

test('TOOLS and CLI_COMMANDS are complete and runnable', async () => {
  const names = TOOLS.map((t) => t.name);
  for (const n of ['disasm_list_functions', 'disasm_function', 'disasm_pseudocode', 'disasm_xrefs', 'disasm_callgraph', 'disasm_search', 'disasm_find_references', 'disasm_call_paths', 'disasm_at']) assert.ok(names.includes(n), n);
  for (const t of TOOLS) { assert.match(t.name, /^disasm_[a-z_]+$/); assert.ok(t.inputSchema.path); }
  const r = (await TOOLS.find((t) => t.name === 'disasm_function')!.run({ path: P('hello-arm64.elf'), function: 'fib' })) as { summary: { calls: { name: string }[] } };
  assert.ok(r.summary.calls.some((c) => c.name === 'fib'));
  const cmd = CLI_COMMANDS.find((c) => c.name === 'disasm-functions')!;
  const orig = process.stdout.write.bind(process.stdout);
  let captured = '';
  (process.stdout as { write: unknown }).write = (s: string) => { captured += s; return true; };
  try { assert.equal(await cmd.run([P('hello-x64.elf'), '--filter', 'deep', '--json']), 0); } finally { (process.stdout as { write: unknown }).write = orig; }
  assert.equal(JSON.parse(captured).total, 3);
  assert.equal(await CLI_COMMANDS.find((c) => c.name === 'disasm')!.run([]), 2);
});

test('analyzer adds report.meta.disasm and key function summaries', async () => {
  const bytes = new Uint8Array(readFileSync(P('hello-x64.elf')));
  const report = { findings: [] as unknown[], meta: {} as Record<string, unknown> };
  const ctx = { bytes, name: 'hello', format: 'elf', options: { maxStrings: 100, recurse: false, maxDepth: 1 }, depth: 0, report } as never;
  assert.ok(disasmAnalyzer.applies(ctx));
  await disasmAnalyzer.run(ctx);
  const meta = report.meta.disasm as { functions: number; keyFunctions: { name: string }[]; arch: string };
  assert.equal(meta.arch, 'x86_64');
  assert.ok(meta.functions >= 9);
  assert.ok(meta.keyFunctions.some((f) => f.name === 'main'));
});
